17	    static TraversalResult traverseAllComponents(Graph graph) {
18	        TraversalState traversalState = TraversalState.create(graph);
19	
20	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
21	            if (!traversalState.hasVisited(vertex)) {
22	                traversalState.traverseComponent(vertex);
23	            }
24	        }
25	
26	        return traversalState.result();
