29	    private static final class TraversalState {
30	        private final Graph graph;
31	        private final boolean[] visited;
32	        private final List<Integer> traversalOrder;
33	
34	        private TraversalState(Graph graph) {
35	            this.graph = graph;
36	            visited = new boolean[graph.vertexCount()];
37	            traversalOrder = new ArrayList<>();
38	        }
39	
40	        static TraversalState create(Graph graph) {
41	            if (graph == null) {
42	                throw new IllegalArgumentException("Graph cannot be null.");
43	            }
44	            return new TraversalState(graph);
45	        }
46	
47	        boolean hasVisited(int vertex) {
48	            return visited[vertex];
49	        }
50	
51	        TraversalResult result() {
52	            return TraversalResult.fromVisitOrder(traversalOrder);
53	        }
54	
55	        void traverseComponent(int startVertex) {
56	            Deque<Integer> queue = new ArrayDeque<>();
57	            visited[startVertex] = true;
58	            queue.add(startVertex);
59	
60	            while (!queue.isEmpty()) {
61	                int currentVertex = queue.remove();
62	                traversalOrder.add(currentVertex);
63	
64	                for (int neighbor : graph.neighborsOf(currentVertex)) {
65	                    if (!visited[neighbor]) {
66	                        visited[neighbor] = true;
67	                        queue.add(neighbor);
68	                    }
69	                }
70	            }
71	        }
72	    }
73	}

